:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
  image-rendering: pixelated;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--accent);
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.5);
  padding: 2rem;
  width: 100%;
  max-width: 400px;
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.mode-toggle {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
  justify-content: center;
}

.mode-btn {
  flex: 1;
  padding: 0.6rem 0.5rem;
  font-family: var(--font);
  font-size: 0.9rem;
  background: transparent;
  color: var(--muted);
  border: 2px solid var(--muted);
  cursor: pointer;
  transition: all 0.1s;
}

.mode-btn.active {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
  font-weight: bold;
}

.mode-btn:hover {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.timer {
  font-size: 5rem;
  font-weight: bold;
  letter-spacing: 4px;
  margin: 1.5rem 0;
  color: var(--text);
  text-shadow: 4px 4px 0 #000;
  line-height: 1;
}

.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

.control-btn {
  padding: 0.8rem 1.5rem;
  font-family: var(--font);
  font-size: 1.1rem;
  background: var(--accent);
  color: var(--bg);
  border: 3px solid var(--accent);
  cursor: pointer;
  font-weight: bold;
  transition: all 0.1s;
  box-shadow: 4px 4px 0 #000;
}

.control-btn:hover {
  background: var(--text);
  border-color: var(--text);
  color: var(--bg);
}

.control-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.control-btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

@media (max-width: 400px) {
  .timer {
    font-size: 3.5rem;
  }
  .card {
    padding: 1.5rem;
  }
  .control-btn {
    padding: 0.6rem 1rem;
    font-size: 1rem;
  }
}

(function() {
  const WORK_TIME = 25 * 60;
  const BREAK_TIME = 5 * 60;

  const timerEl = document.getElementById('timer');
  const startPauseBtn = document.getElementById('start-pause');
  const resetBtn = document.getElementById('reset');
  const workModeBtn = document.getElementById('work-mode');
  const breakModeBtn = document.getElementById('break-mode');

  let mode = 'work';
  let timeLeft = WORK_TIME;
  let isRunning = false;
  let intervalId = null;

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60).toString().padStart(2, '0');
    const s = (seconds % 60).toString().padStart(2, '0');
    return m + ':' + s;
  }

  function updateDisplay() {
    timerEl.textContent = formatTime(timeLeft);
  }

  function setMode(newMode) {
    mode = newMode;
    timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
    isRunning = false;
    clearInterval(intervalId);
    intervalId = null;
    startPauseBtn.textContent = 'Start';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
    workModeBtn.classList.toggle('active', mode === 'work');
    workModeBtn.setAttribute('aria-pressed', mode === 'work');
    breakModeBtn.classList.toggle('active', mode === 'break');
    breakModeBtn.setAttribute('aria-pressed', mode === 'break');
    updateDisplay();
  }

  function tick() {
    timeLeft--;
    updateDisplay();
    if (timeLeft <= 0) {
      clearInterval(intervalId);
      intervalId = null;
      isRunning = false;
      startPauseBtn.textContent = 'Start';
      startPauseBtn.setAttribute('aria-label', 'Start timer');
      // Auto-switch mode on completion
      if (mode === 'work') {
        setMode('break');
      } else {
        setMode('work');
      }
    }
  }

  function startTimer() {
    if (isRunning) return;
    isRunning = true;
    startPauseBtn.textContent = 'Pause';
    startPauseBtn.setAttribute('aria-label', 'Pause timer');
    intervalId = setInterval(tick, 1000);
  }

  function pauseTimer() {
    if (!isRunning) return;
    isRunning = false;
    clearInterval(intervalId);
    intervalId = null;
    startPauseBtn.textContent = 'Start';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
  }

  startPauseBtn.addEventListener('click', function() {
    if (isRunning) {
      pauseTimer();
    } else {
      startTimer();
    }
  });

  resetBtn.addEventListener('click', function() {
    clearInterval(intervalId);
    intervalId = null;
    isRunning = false;
    timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
    startPauseBtn.textContent = 'Start';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
    updateDisplay();
  });

  workModeBtn.addEventListener('click', function() {
    setMode('work');
  });

  breakModeBtn.addEventListener('click', function() {
    setMode('break');
  });

  // Initialize
  updateDisplay();
})();
